import re
html = open('/home/user/altair_project/chart.html').read()
m = re.search(r\"const spec = (\{.*?\});\s*\n\", html, re.S)
import json
spec = json.loads(m.group(1))
print('top-level keys:', list(spec.keys()))
print('data:', spec.get('data'))
print('has vconcat:', 'vconcat' in spec)
print('top params:', spec.get('params'))
for i, sub in enumerate(spec.get('vconcat', [])):
    print(f'--- sub[{i}] keys: {list(sub.keys())}')
    print(f'    title: {sub.get(\"title\")}')
    print(f'    height: {sub.get(\"height\")}, width: {sub.get(\"width\")}')
    if 'params' in sub:
        print(f'    params:', [p.get(\"name\") for p in sub['params']])
        for p in sub['params']:
            print(f'      sel:', p.get(\"select\"), 'name:', p.get(\"name\"))
    if 'mark' in sub:
        print(f'    mark:', sub.get(\"mark\"))
    if 'encoding' in sub:
        for k, v in sub['encoding'].items():
            scale = v.get('scale') if isinstance(v, dict) else None
            dom = scale.get('domain') if isinstance(scale, dict) else None
            print(f'    enc.{k}: scale.domain = {dom!r}, type={v.get(\"type\")}')
    if 'layer' in sub:
        for j, lyr in enumerate(sub['layer']):
            print(f'    layer[{j}] mark:', lyr.get('mark'))
            if 'transform' in lyr:
                print(f'      transforms:', [(t.get('type'), list(t.keys())) for t in lyr['transform']])
            if 'encoding' in lyr:
                for k, v in lyr['encoding'].items():
                    print(f'      enc.{k}: {v}')
